Web Frontend.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(web_frontend, "Web Frontend") {
    Component(spa_container, "SPA Container", "React", "Powers the Single Page Application container with responsive UI and sub-second EMR rendering.")
}

System_Ext(api_gateway, "API Gateway", "Node.js", "Implements the API Gateway for routing, OAuth/MFA enforcement, and security policies.")

Rel(spa_container, api_gateway, "Sends HTTPS (TLS 1.3) requests", "HTTPS (TLS 1.3)")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Routing_and_Perimeter_Defense, "Routing and Perimeter Defense", "Node.js & Envoy", "Handles routing, perimeter defense, and entry point for incoming client requests.")
    Component(Authentication_Manager, "Authentication Manager", "OAuth 2.0 / OIDC and MFA", "Enforces OAuth/MFA authentication and security protocols for incoming requests.")
}

Rel(Routing_and_Perimeter_Defense, Authentication_Manager, "Delegates authentication and token validation")

@enduml

Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database container

Container_Boundary(database, "Database") {
    Component(patroni_coordinator, "Patroni Coordinator", "Patroni", "Manages PostgreSQL high availability, automatic failover, and consensus cluster state.")
    Component(pgbouncer_connection_pooler, "PgBouncer Connection Pooler", "PgBouncer", "Manages and optimizes database connection pooling for high-throughput microservice requests.")
    Component(postgresql_data_engine, "PostgreSQL Data Engine", "PostgreSQL 16 with pgcrypto", "Provides ACID-compliant relational data storage with AES-256 encryption at rest for patient EMR and billing data.")
}

Rel(pgbouncer_connection_pooler, postgresql_data_engine, "Routes and multiplexes queries")
Rel(patroni_coordinator, postgresql_data_engine, "Monitors and manages health and failover")
@enduml
